// FRANCE MAP PAGE — Vraie carte Leaflet (OpenStreetMap)
// ════════════════════════════════════════════════════════════════════════════════

// Coordonnées GPS réelles des villes françaises
const CITY_LATLNG = {
  "paris":        [48.8566, 2.3522],
  "lyon":         [45.7640, 4.8357],
  "marseille":    [43.2965, 5.3698],
  "toulouse":     [43.6047, 1.4442],
  "bordeaux":     [44.8378, -0.5792],
  "nantes":       [47.2184, -1.5536],
  "strasbourg":   [48.5734, 7.7521],
  "lille":        [50.6292, 3.0573],
  "nice":         [43.7102, 7.2620],
  "rennes":       [48.1173, -1.6778],
  "montpellier":  [43.6108, 3.8767],
  "grenoble":     [45.1885, 5.7245],
  "dijon":        [47.3220, 5.0415],
  "angers":       [47.4784, -0.5632],
  "reims":        [49.2583, 4.0317],
  "metz":         [49.1193, 6.1757],
  "tours":        [47.3941, 0.6848],
  "clermont":     [45.7797, 3.0863],
  "rouen":        [49.4432, 1.0993],
  "toulon":       [43.1242, 5.9280],
  "fontainebleau":[48.4000, 2.7014],
  "versailles":   [48.8044, 2.1204],
};

function guessLatLng(activity) {
  const hay = (activity.location + " " + activity.title).toLowerCase();
  for (const [city, latlng] of Object.entries(CITY_LATLNG)) {
    if (hay.includes(city)) return latlng;
  }
  // jitter stable basé sur l'id pour éviter les superpositions
  const seed = activity.id.split("").reduce((s,c)=>s+c.charCodeAt(0),0);
  return [46.5 + (seed%20)/10 - 1, 2.3 + (seed%13)/10 - 0.6];
}

function MapPage({ activities, currentUser, onOpenActivity, userPos, onRequestLocation, viewRef, t }) {
  const mapRef = useRef(null);
  const leafletRef = useRef(null);
  const markersRef = useRef([]);
  const [selected, setSelected] = useState(() => viewRef?.current?.selectedId ? (activities.find(a => a.id === viewRef.current.selectedId) || null) : null);
  const [clusterList, setClusterList] = useState(null);
  const renderRef = useRef(null);
  const meMarkerRef = useRef(null);
  const centeredRef = useRef(!!userPos || !!viewRef?.current?.center);
  const [filterCat, setFilterCat] = useState("Tous");
  const [mapReady] = useState(true);
  const firstFilterRef = useRef(true);
  useEffect(()=>{ if (firstFilterRef.current) { firstFilterRef.current = false; return; } setSelected(null); setClusterList(null); },[filterCat]);
  useEffect(()=>{ if (viewRef) viewRef.current = { ...viewRef.current, selectedId: selected?.id || null }; },[selected]);
  const isDark = t.bg === "#0D0A12";

  const filtered = activities.filter(a => filterCat === "Tous" || a.category === filterCat);
  const nearCount = userPos ? filtered.filter(a => a.lat != null && distKm(userPos, { lat:a.lat, lng:a.lng }) <= 50).length : 0;



  // Init carte
  useEffect(() => {
    if (!mapReady || !mapRef.current || leafletRef.current) return;
    

    const map = L.map(mapRef.current, {
      center: viewRef?.current?.center || (userPos ? [userPos.lat, userPos.lng] : [46.6, 2.3]),
      zoom: viewRef?.current?.zoom ?? (userPos ? 11 : 6),
      zoomControl: false,
      attributionControl: false,
    });

    // Tuile selon le thème — style sombre ou clair
    const tileUrl = "https://tile.openstreetmap.org/{z}/{x}/{y}.png";

    L.tileLayer(tileUrl, { maxZoom: 19, attribution: "© OpenStreetMap" }).addTo(map);
    L.control.zoom({ position: "bottomright" }).addTo(map);
    L.control.attribution({ prefix: false }).addTo(map);

    leafletRef.current = map;
    map.on("zoomend", () => renderRef.current && renderRef.current());
    map.on("moveend", () => { if (viewRef) { const c = map.getCenter(); viewRef.current = { ...viewRef.current, center: [c.lat, c.lng], zoom: map.getZoom() }; } });
    map.on("click", () => { setSelected(null); setClusterList(null); });
    mapRef.current.classList.toggle("grouz-map-dark", isDark);
    setTimeout(()=>map.invalidateSize(),150);
    const ro = new ResizeObserver(()=>map.invalidateSize());
    ro.observe(mapRef.current);

    return () => {
      ro.disconnect();
      map.remove();
      leafletRef.current = null;
    };
  }, [mapReady]);

  // Point bleu "tu es ici" + recentrage une seule fois quand la position arrive
  useEffect(() => {
    const map = leafletRef.current;
    if (!map) return;
    if (meMarkerRef.current) { meMarkerRef.current.remove(); meMarkerRef.current = null; }
    if (!userPos) return;
    meMarkerRef.current = L.marker([userPos.lat, userPos.lng], {
      icon: L.divIcon({ className:"", html:'<div style="width:18px;height:18px;border-radius:50%;background:#3A8FE8;border:3px solid #fff;box-shadow:0 0 0 7px rgba(58,143,232,0.28)"></div>', iconSize:[18,18], iconAnchor:[9,9] }),
      interactive:false, zIndexOffset:-100,
    }).addTo(map);
    if (!centeredRef.current) { centeredRef.current = true; map.setView([userPos.lat, userPos.lng], 11); }
  }, [userPos?.lat, userPos?.lng, mapReady]);

  // Pins + regroupement par zone (recalculé à chaque zoom)
  const sig = filtered.map(a => `${a.id}:${a.accepted?.length}:${a.maxPeople}:${a.lat}`).join("|") + currentUser.id;
  useEffect(() => {
    if (!leafletRef.current || !mapReady) return;
    const map = leafletRef.current;

    const render = () => {
      markersRef.current.forEach(m => m.remove());
      markersRef.current = [];
      const zoom = map.getZoom();

      // 1. regroupe les sorties qui sont proches (moins de 50 px à l'écran)
      const clusters = [];
      filtered.forEach(act => {
        const ll = act.lat != null ? [act.lat, act.lng] : guessLatLng(act);
        const pt = map.project(L.latLng(ll), zoom);
        const c = clusters.find(c => c.pt.distanceTo(pt) < 50);
        if (c) {
          c.items.push({ act, ll });
          c.latSum += ll[0]; c.lngSum += ll[1];
          c.pt = map.project(L.latLng(c.latSum / c.items.length, c.lngSum / c.items.length), zoom);
        } else {
          clusters.push({ items: [{ act, ll }], latSum: ll[0], lngSum: ll[1], pt });
        }
      });

      // 2. dessine un pin seul ou une bulle avec le nombre de sorties
      clusters.forEach(c => {
        if (c.items.length === 1) {
          const { act, ll } = c.items[0];
          const isMember = act.accepted?.some(u => u.id === currentUser.id);
          const pinColor = isMember ? "#AAEE00" : "#E8008A";
          const icon = CAT_ICONS[act.category] || "📍";
          const spotsLeft = act.maxPeople - (act.accepted?.length || 0);
          const markerIcon = L.divIcon({
            className: "",
            html: `
              <div style="position:relative;display:flex;flex-direction:column;align-items:center;cursor:pointer;">
                <div style="width:38px;height:38px;border-radius:50% 50% 50% 0;background:${pinColor};border:2.5px solid #fff;display:flex;align-items:center;justify-content:center;font-size:16px;transform:rotate(-45deg);box-shadow:0 3px 14px ${pinColor}88;">
                  <span style="transform:rotate(45deg);line-height:1">${icon}</span>
                </div>
                ${spotsLeft===0?`<div style="position:absolute;top:-6px;right:-6px;background:#E8008A;color:#fff;font-size:8px;font-family:DM Mono,monospace;padding:1px 4px;border-radius:6px;font-weight:700;white-space:nowrap">COMPLET</div>`:""}
              </div>`,
            iconSize: [38, 48], iconAnchor: [19, 48],
          });
          const marker = L.marker(ll, { icon: markerIcon }).addTo(map);
          marker.on("click", () => {
            setClusterList(null); setSelected(act);
            map.flyTo(ll, Math.max(map.getZoom(), 14), { duration: 0.8 });
          });
          markersRef.current.push(marker);
        } else {
          const n = c.items.length;
          const center = [c.latSum / n, c.lngSum / n];
          const bubble = L.divIcon({
            className: "",
            html: `<div style="width:50px;height:50px;border-radius:50%;background:linear-gradient(135deg,#E8008A,#7B00C8);border:3px solid #fff;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#fff;font-family:DM Mono,monospace;box-shadow:0 4px 18px rgba(232,0,138,0.6);cursor:pointer;line-height:1;">
                     <span style="font-size:17px;font-weight:700">${n}</span><span style="font-size:7px;letter-spacing:0.05em;margin-top:2px">SORTIES</span></div>`,
            iconSize: [50, 50], iconAnchor: [25, 25],
          });
          const marker = L.marker(center, { icon: bubble }).addTo(map);
          marker.on("click", () => {
            const bounds = L.latLngBounds(c.items.map(i => i.ll));
            const tiny = bounds.getNorthEast().distanceTo(bounds.getSouthWest()) < 30; // même endroit
            if (tiny || map.getZoom() >= 15) {
              // trop proches pour se séparer : on liste les sorties de la zone
              setSelected(null); setClusterList(c.items.map(i => i.act));
              map.flyTo(bounds.getCenter(), Math.max(map.getZoom(), 14), { duration: 0.6 });
            } else {
              setClusterList(null); setSelected(null);
              map.flyToBounds(bounds, { padding: [70, 70], maxZoom: 16, duration: 0.8 });
            }
          });
          markersRef.current.push(marker);
        }
      });
    };

    renderRef.current = render;
    render();
  }, [sig, mapReady]);

  // Recharge les tiles si le thème change
  useEffect(() => {
    if (!leafletRef.current || !mapReady) return;
    
    const map = leafletRef.current;
    map.eachLayer(l => { if (l._url) map.removeLayer(l); });
    const tileUrl = "https://tile.openstreetmap.org/{z}/{x}/{y}.png";
    L.tileLayer(tileUrl, { maxZoom: 19, attribution: "© OpenStreetMap" }).addTo(map);
    mapRef.current?.classList.toggle("grouz-map-dark", isDark);
  }, [isDark, mapReady]);

  return (
    <div style={{ display:"flex", flexDirection:"column", height:"100%", background:t.bg }}>
      {/* Header */}
      <div style={{ padding:"14px 16px 8px", flexShrink:0 }}>
        <h2 style={{ fontFamily:"'Fraunces',serif", fontSize:22, fontStyle:"italic", margin:"0 0 10px", background:t.gradient, WebkitBackgroundClip:"text", WebkitTextFillColor:"transparent", backgroundClip:"text" }}>
          Carte des sorties
        </h2>
        <div style={{ display:"flex", gap:6, overflowX:"auto", paddingBottom:4 }}>
          {["Tous",...CATEGORIES.filter(c=>c!=="Tous")].map(c=>(
            <button key={c} onClick={()=>setFilterCat(c)} style={{ padding:"5px 12px", borderRadius:20, border:`1px solid ${filterCat===c?"#E8008A":t.border}`, background:filterCat===c?"#E8008A":"transparent", color:filterCat===c?"#fff":t.text3, cursor:"pointer", fontSize:10, fontFamily:"'DM Mono',monospace", whiteSpace:"nowrap", fontWeight:filterCat===c?700:400, flexShrink:0 }}>
              {CAT_ICONS[c]} {c}
            </button>
          ))}
        </div>
      </div>

      {/* Map container */}
      <div style={{ flex:1, position:"relative", margin:"0 12px", borderRadius:20, overflow:"hidden", border:`1px solid ${t.border}`, minHeight:260, isolation:"isolate", zIndex:0 }}>
        {!mapReady && (
          <div style={{ position:"absolute", inset:0, display:"flex", alignItems:"center", justifyContent:"center", background:t.bg2, zIndex:10 }}>
            <div style={{ textAlign:"center" }}>
              <div style={{ fontSize:32, marginBottom:12 }}>🗺</div>
              <p style={{ color:t.text3, fontFamily:"'DM Mono',monospace", fontSize:12 }}>Chargement de la carte…</p>
            </div>
          </div>
        )}
        <div ref={mapRef} style={{ position:"absolute", inset:0 }} />

        {/* Mini-fiche de la sortie sélectionnée (haut gauche) : un clic ouvre la fiche complète */}
        {selected && (
          <div onClick={()=>onOpenActivity(selected)} style={{ position:"absolute", top:12, left:12, zIndex:1000, maxWidth:"min(250px, calc(100% - 150px))", display:"flex", alignItems:"center", gap:10, background:t.bg+"F2", backdropFilter:"blur(8px)", border:"1px solid #E8008A66", borderRadius:14, padding:"8px 10px", cursor:"pointer", boxShadow:"0 6px 20px rgba(0,0,0,0.35)", animation:"slideUp 0.2s ease" }}>
            <div style={{ width:34, height:34, borderRadius:"50%", background:t.gradient, display:"flex", alignItems:"center", justifyContent:"center", fontSize:16, flexShrink:0 }}>{CAT_ICONS[selected.category]}</div>
            <div style={{ flex:1, minWidth:0 }}>
              <p style={{ margin:0, fontFamily:"'Fraunces',serif", fontSize:13, color:t.text, whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{selected.title}</p>
              <p style={{ margin:"2px 0 0", fontSize:9, color:t.text3, fontFamily:"'DM Mono',monospace", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{new Date(selected.date).toLocaleDateString("fr-FR",{day:"numeric",month:"short"})} · {selected.time} · {selected.location}</p>
            </div>
            <button onClick={e=>{ e.stopPropagation(); setSelected(null); }} style={{ width:22, height:22, borderRadius:"50%", background:t.bg3, border:`1px solid ${t.border}`, color:t.text3, cursor:"pointer", fontSize:10, flexShrink:0, padding:0 }}>✕</button>
          </div>
        )}

        {/* Bouton "ma position" */}
        <button onClick={()=>{ if (userPos && leafletRef.current) leafletRef.current.flyTo([userPos.lat, userPos.lng], 12, { duration:0.8 }); else onRequestLocation(); }}
          aria-label="Ma position" style={{ position:"absolute", right:10, bottom:84, zIndex:1000, width:40, height:40, borderRadius:"50%", background:t.bg+"F2", border:`1px solid ${t.border}`, color:userPos?"#3A8FE8":t.text3, fontSize:18, cursor:"pointer", boxShadow:"0 4px 14px rgba(0,0,0,0.3)" }}>◎</button>

        {/* Counter overlay */}
        <div style={{ position:"absolute", bottom:12, left:12, zIndex:1000, background:t.bg+"EE", backdropFilter:"blur(8px)", borderRadius:10, padding:"6px 12px", border:`1px solid ${t.border}`, pointerEvents:"none" }}>
          <span style={{ fontSize:10, color:t.text2, fontFamily:"'DM Mono',monospace", fontWeight:700 }}>
            📍 {userPos ? `${nearCount} près de toi` : `${filtered.length} sortie${filtered.length>1?"s":""}`}
          </span>
        </div>

        {/* Legend overlay */}
        <div style={{ position:"absolute", top:12, right:12, zIndex:1000, background:t.bg+"EE", backdropFilter:"blur(8px)", borderRadius:10, padding:"8px 12px", border:`1px solid ${t.border}` }}>
          <div style={{ display:"flex", alignItems:"center", gap:6, marginBottom:4 }}>
            <div style={{ width:10, height:10, borderRadius:"50%", background:"#E8008A" }}/>
            <span style={{ fontSize:9, color:t.text2, fontFamily:"'DM Mono',monospace" }}>Sortie dispo</span>
          </div>
          <div style={{ display:"flex", alignItems:"center", gap:6 }}>
            <div style={{ width:10, height:10, borderRadius:"50%", background:"#AAEE00" }}/>
            <span style={{ fontSize:9, color:t.text2, fontFamily:"'DM Mono',monospace" }}>Inscrit ✓</span>
          </div>
        </div>
      </div>

      {/* Liste des sorties d'une zone regroupée */}
      {clusterList && (
        <div style={{ margin:"10px 12px 0", background:t.bg2, border:`2px solid #E8008A55`, borderRadius:18, padding:"12px 14px", flexShrink:0, maxHeight:"38%", overflowY:"auto", boxShadow:"0 8px 28px rgba(232,0,138,0.18)", animation:"slideUp 0.2s ease" }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:8 }}>
            <span style={{ fontSize:11, color:"#E8008A", fontFamily:"'DM Mono',monospace", fontWeight:700 }}>📍 {clusterList.length} SORTIES DANS CETTE ZONE</span>
            <button onClick={()=>setClusterList(null)} style={{ width:28, height:28, borderRadius:"50%", background:t.bg3, border:`1px solid ${t.border}`, color:t.text3, cursor:"pointer", fontSize:12 }}>✕</button>
          </div>
          {clusterList.map(a=>(
            <div key={a.id} onClick={()=>{ onOpenActivity(a); setClusterList(null); }} style={{ display:"flex", alignItems:"center", gap:10, padding:"8px 0", borderTop:`1px solid ${t.border}`, cursor:"pointer" }}>
              <span style={{ fontSize:20 }}>{CAT_ICONS[a.category]}</span>
              <div style={{ flex:1, minWidth:0 }}>
                <p style={{ margin:0, fontFamily:"'Fraunces',serif", fontSize:14, color:t.text, whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{a.title}</p>
                <p style={{ margin:"2px 0 0", fontSize:10, color:t.text3, fontFamily:"'DM Mono',monospace" }}>{new Date(a.date).toLocaleDateString("fr-FR",{day:"numeric",month:"short"})} · {a.time} · {a.accepted?.length}/{a.maxPeople}</p>
              </div>
              <span style={{ fontSize:11, color:"#E8008A", fontFamily:"'DM Mono',monospace", fontWeight:700 }}>Voir →</span>
            </div>
          ))}
        </div>
      )}

      <div style={{ height:8, flexShrink:0 }}/>
    </div>
  );
}

// ════════════════════════════════════════════════════════════════════════════════
// MAIN APP
// ════════════════════════════════════════════════════════════════════════════════
const fmtKm = km => km < 1 ? "< 1 km" : km < 10 ? `${km.toFixed(1).replace(".", ",")} km` : `${Math.round(km)} km`;

const distKm = (a, b) => {
  const R = 6371, r = x => x * Math.PI / 180;
  const dLat = r(b.lat - a.lat), dLng = r(b.lng - a.lng);
  const h = Math.sin(dLat/2)**2 + Math.cos(r(a.lat)) * Math.cos(r(b.lat)) * Math.sin(dLng/2)**2;
  return 2 * R * Math.asin(Math.sqrt(h));
};

function GeoAskModal({ onAllow, onLater, t }) {
  return (
    <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.7)",backdropFilter:"blur(6px)",zIndex:300,display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
      <div style={{background:t.bg2,border:`1px solid ${t.border}`,borderRadius:20,maxWidth:380,width:"100%",padding:28,textAlign:"center"}}>
        <div style={{fontSize:44,marginBottom:10}}>📍</div>
        <h2 style={{fontFamily:"'Fraunces',serif",fontSize:22,color:t.text,margin:"0 0 10px"}}>Autoriser la localisation ?</h2>
        <p style={{color:t.text2,fontFamily:"'DM Sans',sans-serif",fontSize:14,lineHeight:1.5,margin:"0 0 10px"}}>GrouZ utilise ta position pour centrer la carte sur toi et te proposer des sorties et des personnes près de chez toi.</p>
        <p style={{color:t.text3,fontFamily:"'DM Mono',monospace",fontSize:11,lineHeight:1.5,margin:"0 0 20px"}}>Ta position exacte n'est jamais montrée : les autres voient seulement ta ville et une distance approximative. Tu peux arrêter à tout moment.</p>
        <Btn accent onClick={onAllow} t={t} style={{width:"100%",padding:14,marginBottom:10}}>AUTORISER</Btn>
        <button onClick={onLater} style={{background:"none",border:"none",color:t.text3,fontFamily:"'DM Mono',monospace",fontSize:12,cursor:"pointer",padding:8}}>Plus tard</button>
      </div>
    </div>
  );
}

function NearbySheet({ users, loading, radius, onRadius, geoStatus, hasPos, sharing, onToggleShare, onAskLocation, onAdd, onOpenProfile, onClose, t }) {
  const [sent, setSent] = useState({});
  const msg = (txt) => <p style={{color:t.text3,fontFamily:"'DM Sans',sans-serif",fontSize:13,lineHeight:1.5,textAlign:"center",margin:"18px 6px"}}>{txt}</p>;
  return (
    <div onClick={onClose} style={{position:"fixed",inset:0,zIndex:120,background:"rgba(0,0,0,0.5)",backdropFilter:"blur(3px)"}}>
      <div onClick={e=>e.stopPropagation()} style={{position:"absolute",top:"calc(56px + env(safe-area-inset-top, 0px))",left:12,right:12,margin:"0 auto",maxWidth:460,maxHeight:"calc(100% - 140px)",overflowY:"auto",background:t.bg2,border:`1px solid ${t.border}`,borderRadius:18,padding:"16px 16px 12px",boxShadow:"0 16px 48px rgba(0,0,0,0.5)",animation:"slideUp 0.2s ease"}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12}}>
          <h3 style={{fontFamily:"'Fraunces',serif",fontSize:20,color:t.text,margin:0}}>👋 Près de toi</h3>
          <button onClick={onClose} style={{background:"none",border:"none",color:t.text3,fontSize:20,cursor:"pointer"}}>✕</button>
        </div>
        <div style={{display:"flex",gap:6,marginBottom:6}}>
          {[25,50,150].map(r=>(
            <button key={r} onClick={()=>onRadius(r)} style={{padding:"5px 12px",borderRadius:20,border:`1px solid ${radius===r?"#E8008A":t.border}`,background:radius===r?"#E8008A":"transparent",color:radius===r?"#fff":t.text3,cursor:"pointer",fontSize:11,fontFamily:"'DM Mono',monospace",fontWeight:radius===r?700:400}}>{r===150?"Région":`${r} km`}</button>
          ))}
        </div>

        {geoStatus==="denied" && msg("La localisation est bloquée pour GrouZ. Autorise-la dans les réglages de ton navigateur (cadenas près de l'adresse), puis recharge la page.")}
        {geoStatus==="unsupported" && msg("Ton appareil ne permet pas la localisation.")}
        {!hasPos && geoStatus!=="denied" && geoStatus!=="unsupported" && (
          <div style={{textAlign:"center",margin:"18px 0"}}>
            {msg("Active ta localisation pour voir les personnes autour de toi.")}
            <Btn accent onClick={onAskLocation} t={t}>📍 Activer la localisation</Btn>
          </div>
        )}
        {hasPos && !sharing && msg("Tu as désactivé le partage de ta zone. Réactive-le plus bas pour voir les autres et apparaître dans leurs suggestions.")}
        {hasPos && sharing && loading && msg("Recherche en cours…")}
        {hasPos && sharing && !loading && users && users.length===0 && msg("Personne dans ta zone pour l'instant. Invite tes amis à rejoindre GrouZ, ou élargis le rayon.")}

        {hasPos && sharing && users && users.map(u=>(
          <div key={u.id} style={{display:"flex",alignItems:"center",gap:12,padding:"10px 0",borderTop:`1px solid ${t.border}`}}>
            <div onClick={()=>onOpenProfile(u)} style={{cursor:"pointer"}}><Avatar user={u} size={46} t={t} /></div>
            <div onClick={()=>onOpenProfile(u)} style={{flex:1,minWidth:0,cursor:"pointer"}}>
              <p style={{color:t.text,fontFamily:"'DM Sans',sans-serif",fontWeight:600,margin:0,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{u.name}</p>
              <p style={{color:t.text3,fontFamily:"'DM Mono',monospace",fontSize:10,margin:"2px 0 0"}}>@{u.pseudo} · {u.age} ans</p>
              <p style={{color:t.accent,fontFamily:"'DM Mono',monospace",fontSize:10,margin:"2px 0 0"}}>📍 {u.city||"Près de toi"} · {u.distance_km<=5?"à moins de 5 km":`à ~${u.distance_km} km`}</p>
            </div>
            {sent[u.id]
              ? <span style={{fontSize:11,color:t.text3,fontFamily:"'DM Mono',monospace"}}>✓ Envoyée</span>
              : <Btn accent small t={t} onClick={()=>{ setSent(p=>({...p,[u.id]:true})); onAdd(u); }}>Ajouter</Btn>}
          </div>
        ))}

        {hasPos && (
          <button onClick={onToggleShare} style={{display:"block",width:"100%",marginTop:10,padding:"10px",background:"none",border:`1px dashed ${t.border}`,borderRadius:10,color:t.text3,fontFamily:"'DM Mono',monospace",fontSize:10,cursor:"pointer"}}>
            {sharing ? "Ne plus apparaître dans les suggestions des autres" : "Réactiver le partage de ma zone"}
          </button>
        )}
        <p style={{color:t.text3,fontFamily:"'DM Mono',monospace",fontSize:9,textAlign:"center",margin:"10px 0 0",lineHeight:1.5}}>Les autres voient uniquement ta ville et une distance approximative, jamais ta position exacte.</p>
      </div>
    </div>
  );
}

function MessagesPage({ friends, last, myId, onOpenDM, onGoFriends, t }) {
  const sorted = [...friends].sort((a,b)=>(last[b.id]?.created_at||"").localeCompare(last[a.id]?.created_at||""));
  return (
    <div style={{padding:"20px 24px",maxWidth:600,margin:"0 auto"}}>
      <h2 style={{fontFamily:"'Fraunces',serif",fontSize:26,color:t.text,margin:"0 0 20px"}}>Messages</h2>
      {sorted.length===0 && (
        <div style={{textAlign:"center",padding:"40px 12px",background:t.bg2,border:`1px dashed ${t.border}`,borderRadius:16}}>
          <p style={{color:t.text3,fontFamily:"'DM Sans',sans-serif",fontSize:14,margin:"0 0 14px",lineHeight:1.5}}>Tu pourras discuter ici avec tes amis.<br/>Ajoute-en depuis leur profil pour commencer.</p>
          <Btn accent onClick={onGoFriends} t={t}>Voir mes amis</Btn>
        </div>
      )}
      {sorted.map(u=>{
        const m = last[u.id];
        const preview = !m ? "Commence la conversation" : (m.sender_id===myId?"Toi : ":"") + dmPreview(m);
        return (
          <div key={u.id} onClick={()=>onOpenDM(u)} style={{display:"flex",alignItems:"center",gap:12,background:t.bg2,border:`1px solid ${t.border}`,borderRadius:14,padding:"12px 16px",marginBottom:8,cursor:"pointer"}}>
            <Avatar user={u} size={46} t={t} />
            <div style={{flex:1,minWidth:0}}>
              <p style={{color:t.text,fontFamily:"'DM Sans',sans-serif",fontWeight:600,margin:0}}>{u.name}</p>
              <p style={{color:t.text3,fontFamily:"'DM Mono',monospace",fontSize:11,margin:"2px 0 0",whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{preview}</p>
            </div>
            {m && <span style={{color:t.text3,fontFamily:"'DM Mono',monospace",fontSize:10}}>{fmtTime(m.created_at)}</span>}
          </div>
        );
      })}
    </div>
  );
}

const colorFor = id => AVATAR_COLORS[(id?.charCodeAt(1)||0) % AVATAR_COLORS.length];
const shapeUser = p => p && ({ ...p, avatar: p.avatar_url || null, avatarColor: colorFor(p.id), friends: [], friendReqs: [] });
const fmtTime = iso => { const d = new Date(iso); return d.getHours().toString().padStart(2,"0")+":"+d.getMinutes().toString().padStart(2,"0"); };
const shapeMsg = m => ({ ...m, senderId: m.sender_id, sender: m.sender ? shapeUser(m.sender) : undefined, time: fmtTime(m.created_at) });
const shapeAct = a => ({ ...a, creator: shapeUser(a.creator), accepted: a.accepted.map(shapeUser), pending: a.pending.map(shapeUser) });
// Une sortie passée (date + heure de début dépassées) n'est plus affichée
const isUpcoming = a => { const d = new Date(`${a.date}T${a.time}:00`); return isNaN(d) || d >= new Date(); };
const fail = e => { console.error(e); alert(e?.message || "Une erreur est survenue."); };

export default function App() {
  // ── Theme (préférence locale à l'appareil) ─────────────────────────────────
  const [darkMode, setDarkMode] = useState(()=>LS.get("sorties_dark",true));
  const t = buildTheme(darkMode);
  const toggleDark = () => { setDarkMode(d=>{ LS.set("sorties_dark",!d); return !d; }); };

  // ── Auth Supabase (session persistante) ────────────────────────────────────
  const [session, setSession] = useState(undefined); // undefined = chargement
  const [me0, setMe0] = useState(null);
  const [loadErr, setLoadErr] = useState(null);
  const [recovery, setRecovery] = useState(false);
  useEffect(()=>{
    api.getSession().then(setSession).catch(()=>setSession(null));
    const sub = api.onAuthChange((s, ev) => { setSession(s); if (ev === "PASSWORD_RECOVERY") setRecovery(true); });
    return ()=>sub.unsubscribe();
  },[]);
  const uid = session?.user?.id;
  useEffect(()=>{
    if (!uid) { setMe0(null); return; }
    setLoadErr(null);
    api.getProfile(uid).then(p=>setMe0(shapeUser(p))).catch(e=>setLoadErr(e.message));
  },[uid]);
  const currentUser = me0;
  const handleLogout = () => api.signOut();

  // ── Données partagées ──────────────────────────────────────────────────────
  const [allUsers, setAllUsers] = useState([]);
  const [friendships, setFriendships] = useState([]);
  const [activities, setActivities] = useState([]);
  const [notifs, setNotifs] = useState([]);
  const [actMessages, setActMessages] = useState({});
  const [dmPartner, setDmPartner] = useState(null);
  const [dmMessages, setDmMessages] = useState([]);
  const dmPartnerRef = useRef(null);
  useEffect(()=>{ dmPartnerRef.current = dmPartner; },[dmPartner]);

  const blockedRef = useRef([]);
  const [blockedIds, setBlockedIds] = useState([]);
  const refreshBlocks = useCallback(()=>api.listBlocks().then(r=>{ const ids=r.map(x=>x.blocked_id); blockedRef.current=ids; setBlockedIds(ids); }).catch(console.error),[]);
  const refreshActivities = useCallback(()=>api.listActivities().then(r=>setActivities(r.map(shapeAct).filter(isUpcoming).filter(a=>!blockedRef.current.includes(a.creator?.id)))).catch(console.error),[]);
  const refreshFriends = useCallback(()=>api.listFriendships().then(setFriendships).catch(console.error),[]);
  const refreshUsers = useCallback(()=>api.listProfiles().then(r=>setAllUsers(r.map(shapeUser))).catch(console.error),[]);
  const refreshNotifs = useCallback(()=>api.listNotifications().then(r=>setNotifs(r.map(n=>({...n,time:fmtTime(n.created_at)})))).catch(console.error),[]);

  useEffect(()=>{
    if (!me0) return;
    refreshBlocks().finally(refreshActivities); refreshFriends(); refreshUsers(); refreshNotifs();
    const n = api.subscribeNotifications(me0.id, row=>{
      if (row.kind==="message" && pageRef.current==="dm" && dmPartnerRef.current?.id===row.ref_id) api.markNotifRead(row.id).finally(refreshNotifs);
      else refreshNotifs();
      refreshActivities(); refreshFriends();
    });
    const d = api.subscribeDMs(me0.id, m=>{
      if (dmPartnerRef.current?.id === m.sender_id) { setDmMessages(prev=>[...prev, shapeMsg(m)]); setPartnerStatus(null); }
      setLastDMs(p=>({...p,[m.sender_id]:m}));
    });
    const feed = api.supabase.channel("feed")
      .on("postgres_changes",{event:"*",schema:"public",table:"activities"},refreshActivities)
      .on("postgres_changes",{event:"*",schema:"public",table:"activity_members"},refreshActivities)
      .on("postgres_changes",{event:"*",schema:"public",table:"profiles"},refreshUsers)
      .subscribe();
    const onVis = () => { if (document.visibilityState==="visible") { refreshNotifs(); refreshActivities(); refreshFriends(); } };
    document.addEventListener("visibilitychange", onVis);
    const poll = setInterval(()=>{ if (document.visibilityState==="visible") refreshNotifs(); }, 30000);
    return ()=>{ [n,d,feed].forEach(c=>api.supabase.removeChannel(c)); document.removeEventListener("visibilitychange", onVis); clearInterval(poll); };
  },[me0?.id]);

  const markNotifsRead = () => api.markAllRead(me0.id).then(refreshNotifs).catch(fail);

  // ── Profil ─────────────────────────────────────────────────────────────────
  const updateCurrentUser = async (u) => {
    try {
      let avatar_url = me0.avatar_url;
      if (u.avatarFile) avatar_url = await api.uploadAvatar(me0.id, u.avatarFile);
      const p = await api.updateProfile(me0.id, { name:u.name, pseudo:u.pseudo, bio:u.bio, age:u.age, gender:u.gender, avatar_url });
      setMe0(shapeUser(p)); refreshUsers();
    } catch(e) { fail(/duplicate|unique/i.test(e.message) ? new Error("Ce pseudo est déjà pris.") : e); }
  };

  // ── Amis ───────────────────────────────────────────────────────────────────
  const [profileUser, setProfileUser] = useState(null);
  const friendIds = me0 ? friendships.filter(f=>f.status==="accepted").map(f=>f.requester_id===me0.id?f.addressee_id:f.requester_id) : [];
  const reqIds = me0 ? friendships.filter(f=>f.status==="pending"&&f.addressee_id===me0.id).map(f=>f.requester_id) : [];
  const me = me0 ? { ...me0, friends: friendIds, friendReqs: reqIds } : null;
  const isFriend = id => friendIds.includes(id);
  const hasPendingReq = id => friendships.some(f=>f.status==="pending"&&f.requester_id===me0?.id&&f.addressee_id===id);
  const sendFriendReq = id => api.sendFriendRequest(me0.id,id).then(refreshFriends).catch(fail);
  const acceptFriendReq = fromId => {
    const f = friendships.find(f=>f.requester_id===fromId&&f.addressee_id===me0.id);
    if (f) api.acceptFriend(f.id).then(refreshFriends).catch(fail);
  };

  // ── Messages privés ────────────────────────────────────────────────────────
  const loadDMs = otherId => api.listDMs(me0.id, otherId).then(r=>setDmMessages(r.map(shapeMsg))).catch(console.error);
  const openDM = (user) => {
    setDmPartner(user); setDmMessages([]); loadDMs(user.id); setPage("dm");
    api.markMessageNotifsRead(me0.id, user.id).then(refreshNotifs).catch(()=>{});
  };
  const sendDM = text => api.sendDM(me0.id, dmPartner.id, text).then(()=>loadDMs(dmPartner.id)).catch(fail);
  const sendVoiceDM = (url, dur, blob) => api.sendDMVoice(me0.id, dmPartner.id, blob, dur).then(()=>loadDMs(dmPartner.id)).catch(fail);

  // ── Vues ───────────────────────────────────────────────────────────────────
  const pageRef = useRef("home");
  const [page, setPage] = useState("home"); // home | detail | profile | friends | settings | dm | map | notifs
  const [selectedId, setSelectedId] = useState(null);
  const [detailBack, setDetailBack] = useState("home");
  const mapViewRef = useRef(null);
  const setSelected = a => setSelectedId(a ? a.id : null);
  const selectedBase = activities.find(a=>a.id===selectedId);
  const selected = selectedBase ? { ...selectedBase, messages: actMessages[selectedId] || [] } : null;
  const [filter, setFilter] = useState("Tous");
  const [search, setSearch] = useState("");
  const [showCreate, setShowCreate] = useState(false);
  const [showNotifs, setShowNotifs] = useState(false);

  const filtered = activities.filter(a=>
    (filter==="Tous"||a.category===filter)&&
    (a.title.toLowerCase().includes(search.toLowerCase())||a.location.toLowerCase().includes(search.toLowerCase()))
  );

  // ── Localisation + personnes proches ───────────────────────────────────────
  const [userPos, setUserPos] = useState(null);           // position précise, reste sur l'appareil
  const [geoStatus, setGeoStatus] = useState("unknown");  // unknown | granted | denied | unsupported | error
  const [showGeoAsk, setShowGeoAsk] = useState(false);
  const [showNearby, setShowNearby] = useState(false);
  const [nearbyRadius, setNearbyRadius] = useState(50);
  const [nearby, setNearby] = useState(null);
  const [nearLoading, setNearLoading] = useState(false);
  const [sharing, setSharing] = useState(()=>LS.get("grouz_share",true));
  const [locVersion, setLocVersion] = useState(0);

  // Enregistre une position ARRONDIE (~1 km) + la ville, visible seulement par soi
  const shareMyZone = async (lat, lng) => {
    const rl = Math.round(lat*100)/100, rg = Math.round(lng*100)/100;
    let city = null;
    try {
      const r = await fetch(`https://api-adresse.data.gouv.fr/reverse/?lon=${rg}&lat=${rl}`);
      city = (await r.json()).features?.[0]?.properties?.city || null;
    } catch {}
    try { await api.saveMyLocation(me0.id, rl, rg, city); setLocVersion(v=>v+1); } catch(e) { console.error(e); }
  };

  const requestLocation = () => {
    if (!navigator.geolocation) { setGeoStatus("unsupported"); return; }
    navigator.geolocation.getCurrentPosition(
      pos => {
        const lat = pos.coords.latitude, lng = pos.coords.longitude;
        setUserPos({ lat, lng }); setGeoStatus("granted"); LS.set("grouz_geo","on");
        if (LS.get("grouz_share",true)) shareMyZone(lat, lng);
      },
      err => setGeoStatus(err.code===1 ? "denied" : "error"),
      { enableHighAccuracy:false, timeout:12000, maximumAge:300000 }
    );
  };

  // Première ouverture : on explique puis on demande ; ensuite mise à jour silencieuse
  useEffect(()=>{
    if (!me0) return;
    if (!navigator.geolocation) { setGeoStatus("unsupported"); return; }
    if (LS.get("grouz_geo")==="on") { requestLocation(); return; }
    if (!LS.get("grouz_geo_asked")) setShowGeoAsk(true);
  },[me0?.id]);

  useEffect(()=>{
    if (!showNearby || !me0) return;
    setNearLoading(true);
    api.nearbyUsers(nearbyRadius).then(r=>setNearby(r.map(shapeUser))).catch(e=>{ console.error(e); setNearby([]); }).finally(()=>setNearLoading(false));
  },[showNearby, nearbyRadius, locVersion, sharing, me0?.id]);

  const toggleSharing = async () => {
    if (sharing) {
      try { await api.removeMyLocation(me0.id); } catch(e) { return fail(e); }
      setSharing(false); LS.set("grouz_share",false); setNearby([]);
    } else {
      setSharing(true); LS.set("grouz_share",true);
      if (userPos) shareMyZone(userPos.lat, userPos.lng); else requestLocation();
    }
  };

  // ── Toucher une notification = aller à l'endroit concerné ──────────────────
  const openNotif = (n) => {
    setShowNotifs(false);
    if (!n.read) api.markNotifRead(n.id).then(refreshNotifs).catch(()=>{});
    // anciennes notifications sans type : on le devine d'après le texte
    const kind = n.kind || (/^(👋)/.test(n.text) || /ami/i.test(n.text) ? "friend_request" : null);
    if (kind==="message") {
      const u = allUsers.find(x=>x.id===n.ref_id);
      if (u) openDM(u); else setPage("messages");
      return;
    }
    if (kind==="friend_request" || kind==="friend_accepted") { refreshFriends(); setPage("friends"); return; }
    let actId = n.ref_id;
    if (!actId) {
      const m = n.text.match(/"([^"]+)"/);
      actId = m && activities.find(a=>a.title===m[1])?.id;
    }
    if (!actId) return;
    const act = activities.find(a=>a.id===actId);
    if (!act) { alert("Cette sortie n'est plus disponible (elle est peut-être passée ou supprimée)."); return; }
    refreshActivities();
    setSelected(act); setDetailBack(page); setPage("detail");
  };

  useEffect(()=>{ pageRef.current = page; },[page]);

  // ── « est en train d'écrire / d'enregistrer » (temps réel, sans base de données) ──
  const [partnerStatus, setPartnerStatus] = useState(null);
  const typingChRef = useRef(null);
  const statusTimerRef = useRef(null);
  useEffect(()=>{
    if (!me0 || !dmPartner || page!=="dm") return;
    const key = [me0.id, dmPartner.id].sort().join("_");
    const ch = api.supabase.channel(`typing-${key}`, { config: { broadcast: { self: false } } });
    ch.on("broadcast", { event: "status" }, ({ payload }) => {
      if (payload.from !== dmPartner.id) return;
      clearTimeout(statusTimerRef.current);
      if (payload.status === "idle") { setPartnerStatus(null); return; }
      setPartnerStatus(payload.status);
      statusTimerRef.current = setTimeout(()=>setPartnerStatus(null), payload.status==="recording" ? 90000 : 5000);
    }).subscribe();
    typingChRef.current = ch;
    return ()=>{ clearTimeout(statusTimerRef.current); setPartnerStatus(null); api.supabase.removeChannel(ch); typingChRef.current = null; };
  },[me0?.id, dmPartner?.id, page==="dm"]);
  const sendStatus = status => { typingChRef.current?.send({ type:"broadcast", event:"status", payload:{ status, from: me0.id } }); };

  // ── Photos, vidéos et GIFs ─────────────────────────────────────────────────
  const sendMediaDM = (kind, file) => api.sendDMMedia(me0.id, dmPartner.id, kind, file).then(()=>loadDMs(dmPartner.id)).catch(fail);
  const sendGifDM = url => api.sendDMGif(me0.id, dmPartner.id, url).then(()=>loadDMs(dmPartner.id)).catch(fail);

  // ── Sécurité : signaler, bloquer, mot de passe, suppression du compte ──────
  const [reportTarget, setReportTarget] = useState(null);
  const [showBlocked, setShowBlocked] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [showDelete, setShowDelete] = useState(false);

  const blockUser = async (u) => {
    if (!window.confirm(`Bloquer ${u.name} ?\n\nCette personne ne pourra plus t'écrire ni t'envoyer de demande d'ami, et ne sera plus dans tes amis.`)) return;
    try { await api.blockUser(me0.id, u.id); } catch(e) { return fail(e); }
    blockedRef.current = [...blockedRef.current, u.id]; setBlockedIds(b=>[...b, u.id]);
    setProfileUser(null); if (page==="dm") setPage("messages");
    refreshFriends(); refreshActivities();
  };
  const unblockUser = async (u) => {
    try { await api.unblockUser(me0.id, u.id); } catch(e) { return fail(e); }
    blockedRef.current = blockedRef.current.filter(id=>id!==u.id); setBlockedIds(b=>b.filter(id=>id!==u.id));
    refreshActivities();
  };
  const sendReport = async (reason, details) => {
    try { await api.reportUser(me0.id, reportTarget.id, reason, details); alert("Merci, ton signalement a bien été envoyé."); setReportTarget(null); }
    catch(e) { fail(e); }
  };
  const deleteAccount = async () => {
    try { await api.deleteMyAccount(me0.id); } catch(e) { return fail(e); }
    ["grouz_geo","grouz_geo_asked","grouz_share"].forEach(k=>LS.set(k,null));
    window.location.reload();
  };

  // ── Fil d'accueil : les sorties les plus proches de toi en premier (toutes catégories) ──
  const feed = (() => {
    const items = filtered.map(a => ({ a, km: userPos && a.lat != null ? distKm(userPos, { lat: a.lat, lng: a.lng }) : null }));
    if (!userPos) return items;
    return items.sort((x, y) => (x.km == null) - (y.km == null) || (x.km ?? 0) - (y.km ?? 0));
  })();

  // ── Liste des conversations (dernier message par ami) ──────────────────────
  const [lastDMs, setLastDMs] = useState({});
  useEffect(()=>{
    if (page!=="messages" || !me0) return;
    api.listRecentDMs().then(rows=>{
      const m={}; rows.forEach(r=>{ const other=r.sender_id===me0.id?r.receiver_id:r.sender_id; if(!m[other]) m[other]=r; });
      setLastDMs(m);
    }).catch(console.error);
  },[page,me0?.id]);

  // Retire automatiquement les sorties qui viennent de passer (vérifié chaque minute)
  useEffect(()=>{ const i=setInterval(()=>setActivities(p=>p.filter(isUpcoming)),60000); return ()=>clearInterval(i); },[]);

  // ── Chat de groupe (chargement + temps réel) ───────────────────────────────
  const loadActMessages = useCallback(id => api.listActivityMessages(id).then(r=>setActMessages(p=>({...p,[id]:r.map(shapeMsg).filter(m=>!blockedRef.current.includes(m.sender_id))}))).catch(console.error),[]);
  useEffect(()=>{
    if (!selectedId || page!=="detail") return;
    loadActMessages(selectedId);
    const ch = api.subscribeActivityMessages(selectedId, ()=>loadActMessages(selectedId));
    return ()=>{ api.supabase.removeChannel(ch); };
  },[selectedId,page]);

  // ── Actions sorties ────────────────────────────────────────────────────────
  const handleJoin = id => api.requestJoin(id, me0.id).then(refreshActivities).catch(fail);
  const handleAccept = (id,userId) => api.acceptMember(id,userId).then(refreshActivities).catch(e=>fail(/complète/i.test(e.message)?new Error("La sortie est complète."):e));
  const handleReject = (id,userId) => api.rejectMember(id,userId).then(refreshActivities).catch(fail);
  const handleSendMessage = (id,text) => api.sendActivityMessage(id,me0.id,text).then(()=>loadActMessages(id)).catch(fail);
  const handleSendVoice = (id,blob,dur) => api.sendActivityVoice(id,me0.id,blob,dur).then(()=>loadActMessages(id)).catch(fail);
  const handleCreate = async (form) => {
    try {
      const [lat,lng] = form.lat != null ? [form.lat, form.lng] : guessLatLng({ ...form, id: String(Date.now()) });
      await api.createActivity(me0.id, { ...form, maxPeople:+form.maxPeople, lat, lng });
      setShowCreate(false); refreshActivities();
    } catch(e) { fail(e); }
  };

  // ── Écrans d'attente / connexion ───────────────────────────────────────────
  if (recovery && session) return <PasswordForm t={t} onDone={()=>{ setRecovery(false); window.history.replaceState({}, "", window.location.pathname); }} onCancel={()=>setRecovery(false)} />;
  if (loadErr) return (
    <div style={{minHeight:"100dvh",background:t.bg,color:t.text,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:14,padding:24,textAlign:"center",fontFamily:"'DM Sans',sans-serif"}}>
      <p>Impossible de charger ton profil.<br/><span style={{color:t.text3,fontSize:12}}>{loadErr}</span></p>
      <Btn accent onClick={handleLogout} t={t}>Se déconnecter</Btn>
    </div>
  );
  if (session===undefined || (session && !me0)) return (
    <div style={{minHeight:"100dvh",background:t.bg,display:"flex",alignItems:"center",justifyContent:"center"}}>
      <img src={LOGO_B64} alt="GrouZ" style={{width:90,height:90,borderRadius:"50%",border:"3px solid #D4AF37"}} />
    </div>
  );
  if (!session) return <AuthScreen onAuth={()=>{}} t={t} />;

  const unreadNotifs = notifs.filter(n=>!n.read).length;
  const unreadMsgs = notifs.filter(n=>!n.read && n.kind==="message").length;
  const friendReqCount = (me.friendReqs||[]).length;

  // Nav tabs: home, notifs, [create button], map, friends, profile
  const NAV = [
    { id:"home",    icon: (active) => (
      <svg width="26" height="26" viewBox="0 0 24 24" fill={active?"currentColor":"none"} stroke="currentColor" strokeWidth={active?0:2} strokeLinecap="round" strokeLinejoin="round">
        <path d="M3 9.5L12 3l9 6.5V20a1 1 0 01-1 1H5a1 1 0 01-1-1V9.5z"/>
        <path d="M9 21V12h6v9" fill="none" stroke="currentColor" strokeWidth="2"/>
      </svg>
    )},
    { id:"messages", icon: (active) => (
      <div style={{position:"relative",display:"inline-flex"}}>
        <svg width="26" height="26" viewBox="0 0 24 24" fill={active?"currentColor":"none"} stroke="currentColor" strokeWidth={active?0:2} strokeLinecap="round" strokeLinejoin="round">
          <path d="M21 15a2 2 0 01-2 2H7l-4 4V5a2 2 0 012-2h14a2 2 0 012 2z"/>
        </svg>
        {unreadMsgs>0&&<span style={{position:"absolute",top:-4,right:-6,minWidth:16,height:16,borderRadius:8,background:"#E8008A",color:"#fff",fontSize:9,fontFamily:"'DM Mono',monospace",display:"flex",alignItems:"center",justifyContent:"center",fontWeight:700,padding:"0 3px"}}>{unreadMsgs}</span>}
      </div>
    )},
    { id:"create",  icon: () => (
      <div style={{width:48,height:48,borderRadius:16,background:t.gradient,display:"flex",alignItems:"center",justifyContent:"center",boxShadow:`0 4px 20px rgba(232,0,138,0.5)`,marginBottom:4}}>
        <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2.5" strokeLinecap="round">
          <line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/>
        </svg>
      </div>
    )},
    { id:"map", icon: (active) => (
      <svg width="26" height="26" viewBox="0 0 24 24" fill={active?"currentColor":"none"} stroke="currentColor" strokeWidth={active?0:2} strokeLinecap="round" strokeLinejoin="round">
        <polygon points="1 6 1 22 8 18 16 22 23 18 23 2 16 6 8 2 1 6"/>
        <line x1="8" y1="2" x2="8" y2="18" fill="none" stroke="currentColor" strokeWidth="2"/>
        <line x1="16" y1="6" x2="16" y2="22" fill="none" stroke="currentColor" strokeWidth="2"/>
      </svg>
    )},
    { id:"friends", icon: (active) => (
      <div style={{position:"relative",display:"inline-flex"}}>
        <svg width="26" height="26" viewBox="0 0 24 24" fill={active?"currentColor":"none"} stroke="currentColor" strokeWidth={active?0:2} strokeLinecap="round" strokeLinejoin="round">
          <path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/>
          <circle cx="9" cy="7" r="4"/>
          <path d="M23 21v-2a4 4 0 00-3-3.87" fill="none" stroke="currentColor" strokeWidth="2"/>
          <path d="M16 3.13a4 4 0 010 7.75" fill="none" stroke="currentColor" strokeWidth="2"/>
        </svg>
        {friendReqCount>0&&<span style={{position:"absolute",top:-4,right:-4,minWidth:16,height:16,borderRadius:8,background:t.accent,color:"#fff",fontSize:9,fontFamily:"'DM Mono',monospace",display:"flex",alignItems:"center",justifyContent:"center",fontWeight:700,padding:"0 3px"}}>{friendReqCount}</span>}
      </div>
    )},
    { id:"profile", icon: (active) => (
      <div style={{borderRadius:"50%",border:`2px solid ${active?t.accent:"transparent"}`,padding:1}}>
        <Avatar user={me} size={28} t={t} />
      </div>
    )},
  ];

  const handleNavClick = (id) => {
    if (id==="create") { setShowCreate(true); return; }
    if (id==="notifs") { setShowNotifs(v=>!v); return; }
    setPage(id);
    setShowNotifs(false);
  };

  // which pages show the bottom nav
  const showNav = !["dm"].includes(page);
  // pages that render inside the scrollable content area
  const BOTTOM_NAV_H = 64;
  const TOP_BAR_H = 56;

  const inputStyle = {flex:1,padding:"11px 16px",borderRadius:12,background:t.input,border:`1px solid ${t.border}`,color:t.text,fontSize:14,fontFamily:"'DM Mono',monospace",outline:"none"};

  return (
    <>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,400;0,9..144,700;1,9..144,400&family=DM+Mono:wght@400;500;700&family=DM+Sans:wght@400;500;600&display=swap');
        *{box-sizing:border-box;margin:0;padding:0;}
        ::-webkit-scrollbar{width:4px}
        ::-webkit-scrollbar-track{background:transparent}
        ::-webkit-scrollbar-thumb{background:linear-gradient(180deg,#E8008A,#7B00C8,#AAEE00);border-radius:4px}
        input,textarea,select{color-scheme:${darkMode?"dark":"light"}}
        input::placeholder,textarea::placeholder{color:${t.border2}}
        @keyframes pulse{0%{opacity:1;transform:scale(1)}50%{opacity:0.5;transform:scale(1.3)}100%{opacity:1;transform:scale(1)}}
        @keyframes wave{0%{transform:scaleY(0.4)}100%{transform:scaleY(1.1)}}
        @keyframes grouz-glow{0%,100%{box-shadow:0 0 20px rgba(232,0,138,0.3)}50%{box-shadow:0 0 40px rgba(170,238,0,0.3)}}
        @media (max-width:768px){input,textarea,select{font-size:16px!important}}
        html,body{overscroll-behavior:none;-webkit-tap-highlight-color:transparent;}
        @keyframes slideUp{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}
        .grouz-map-dark .leaflet-tile-pane{filter:invert(1) hue-rotate(180deg) brightness(0.92) contrast(0.92) saturate(0.7);}
        .grouz-map-dark.leaflet-container{background:#1b1b1f;}
        .leaflet-container{font-family:'DM Sans',sans-serif!important;}
        .leaflet-control-zoom a{background:${t.navBg}!important;color:${t.text}!important;border-color:${t.border}!important;}
        .leaflet-bar{border:1px solid ${t.border}!important;border-radius:10px!important;overflow:hidden;}
      `}</style>

      <div style={{background:t.bg,position:"fixed",inset:0,display:"flex",flexDirection:"column",color:t.text,fontFamily:"'DM Sans',sans-serif",transition:"background 0.2s,color 0.2s",overflow:"hidden"}}>
        {/* Ambient background orbs */}
        <div style={{position:"fixed",top:"-15%",left:"-10%",width:280,height:280,borderRadius:"50%",background:"#E8008A",opacity:0.06,filter:"blur(70px)",pointerEvents:"none",zIndex:0}}/>
        <div style={{position:"fixed",bottom:"-10%",right:"-10%",width:320,height:320,borderRadius:"50%",background:"#AAEE00",opacity:0.05,filter:"blur(70px)",pointerEvents:"none",zIndex:0}}/>
        <div style={{position:"fixed",top:"45%",left:"60%",width:180,height:180,borderRadius:"50%",background:"#7B00C8",opacity:0.04,filter:"blur(50px)",pointerEvents:"none",zIndex:0}}/>
        <div style={{position:"relative",zIndex:1,display:"flex",flexDirection:"column",height:"100%",overflow:"hidden"}}>

        {/* ── TOP BAR (logo + DM icon) ── */}
        {showNav && page!=="detail" && (
          <div style={{height:`calc(${TOP_BAR_H}px + env(safe-area-inset-top, 0px))`,padding:"env(safe-area-inset-top, 0px) 20px 0",display:"flex",alignItems:"center",justifyContent:"space-between",background:t.navBg,flexShrink:0,zIndex:40,borderBottom:`1px solid ${t.border}`}}>
            <button onClick={()=>setShowNearby(true)} aria-label="Personnes près de toi" style={{display:"flex",alignItems:"center",gap:10,background:"none",border:"none",cursor:"pointer",padding:0}}>
              <div style={{position:"relative"}}>
                <div style={{position:"absolute",inset:-2,borderRadius:"50%",background:t.gradient,opacity:0.6,filter:"blur(6px)"}}/>
                <img src={LOGO_B64} alt="GrouZ" style={{width:36,height:36,borderRadius:"50%",objectFit:"cover",position:"relative",border:`2px solid #D4AF37`}} />
              </div>
              <span style={{fontFamily:"'Fraunces',serif",fontSize:22,fontStyle:"italic",background:t.gradient,WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",backgroundClip:"text",fontWeight:700}}>GrouZ</span>
            </button>
            {/* right: notifications */}
            <button onClick={()=>setShowNotifs(v=>!v)} style={{position:"relative",background:"none",border:"none",cursor:"pointer",color:showNotifs?"#E8008A":t.text2,padding:4}}>
              <svg width="26" height="26" viewBox="0 0 24 24" fill={showNotifs?"currentColor":"none"} stroke="currentColor" strokeWidth={showNotifs?0:2} strokeLinecap="round" strokeLinejoin="round">
                <path d="M18 8A6 6 0 006 8c0 7-3 9-3 9h18s-3-2-3-9"/>
                <path d="M13.73 21a2 2 0 01-3.46 0" fill="none" stroke="currentColor" strokeWidth="2"/>
              </svg>
              {unreadNotifs>0&&<span style={{position:"absolute",top:-2,right:-2,minWidth:16,height:16,borderRadius:8,background:"#E8008A",color:"#fff",fontSize:9,fontFamily:"'DM Mono',monospace",display:"flex",alignItems:"center",justifyContent:"center",fontWeight:700,padding:"0 3px"}}>{unreadNotifs}</span>}
            </button>
          </div>
        )}

        {/* ── SCROLL CONTENT ── */}
        <div style={{flex:1,overflowY:"auto",position:"relative"}}>

          {/* HOME */}
          {page==="home"&&(
            <div style={{maxWidth:680,margin:"0 auto",padding:"0 14px",paddingBottom:BOTTOM_NAV_H+16}}>
              <div style={{padding:"28px 8px 20px",textAlign:"center"}}>
                <h1 style={{fontFamily:"'Fraunces',serif",fontSize:"clamp(26px,5vw,44px)",fontStyle:"italic",lineHeight:1.1,marginBottom:8,background:t.gradient,WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",backgroundClip:"text"}}>Trouvez votre prochaine aventure</h1>
                <p style={{color:t.text3,fontFamily:"'DM Mono',monospace",fontSize:11,letterSpacing:"0.08em"}}>ORGANISEZ • RENCONTREZ • VIBREZ</p>
              </div>
              <div style={{marginBottom:20}}>
                <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="🔍  Rechercher une sortie ou un lieu…" style={{...inputStyle,width:"100%",marginBottom:10,padding:"12px 16px",borderRadius:14,fontSize:14,flex:"none"}} />
                <div style={{display:"flex",gap:6,overflowX:"auto",paddingBottom:4}}>
                  {CATEGORIES.map(c=>(
                    <button key={c} onClick={()=>setFilter(c)} style={{padding:"6px 14px",borderRadius:20,border:`1px solid ${filter===c?"#E8008A":t.border}`,background:filter===c?"#E8008A":t.bg2,color:filter===c?"#fff":t.text3,cursor:"pointer",fontSize:11,fontFamily:"'DM Mono',monospace",whiteSpace:"nowrap",transition:"all 0.15s",fontWeight:filter===c?700:400}}>
                      {CAT_ICONS[c]} {c}
                    </button>
                  ))}
                </div>
              </div>
              {feed.length===0
                ? <div style={{textAlign:"center",padding:"56px 0",color:t.text3,fontFamily:"'DM Mono',monospace",fontSize:14}}>Aucune sortie. Soyez le premier !</div>
                : <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(280px,1fr))",gap:14}}>
                    {feed.map(({a,km})=><ActivityCard key={a.id} km={km} activity={a} currentUser={currentUser} onClick={()=>{setSelected(a);setDetailBack("home");setPage("detail");}} t={t} />)}
                  </div>
              }
            </div>
          )}

          {/* DETAIL */}
          {page==="detail"&&selected&&(
            <div style={{display:"flex",flexDirection:"column",height:"100%"}}>
              <ActivityDetail activity={selected} currentUser={currentUser} onBack={()=>setPage(detailBack)} onAccept={handleAccept} onReject={handleReject} onSendMessage={handleSendMessage} onSendVoice={handleSendVoice} onJoin={handleJoin} onOpenProfile={setProfileUser} t={t} />
            </div>
          )}

          {/* NOTIFICATIONS page */}
          {page==="notifs"&&(
            <div style={{maxWidth:600,margin:"0 auto",padding:"20px 16px",paddingBottom:BOTTOM_NAV_H+16}}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:20}}>
                <h2 style={{fontFamily:"'Fraunces',serif",fontSize:24,color:t.text}}>Notifications</h2>
                <button onClick={markNotifsRead} style={{background:"none",border:"none",color:t.accent,fontFamily:"'DM Mono',monospace",fontSize:12,cursor:"pointer"}}>Tout marquer lu</button>
              </div>
              {notifs.length===0&&<p style={{color:t.text3,fontFamily:"'DM Mono',monospace",fontSize:13,textAlign:"center",padding:"48px 0"}}>Aucune notification pour le moment.</p>}
              {notifs.map((n,i)=>(
                <div key={i} style={{display:"flex",alignItems:"flex-start",gap:12,padding:"14px 16px",background:n.read?t.bg2:t.accentBg,border:`1px solid ${n.read?t.border:t.accent+"44"}`,borderRadius:14,marginBottom:8}}>
                  <span style={{fontSize:20,marginTop:2}}>{n.text.startsWith("🔔")?"🔔":n.text.startsWith("✅")?"✅":n.text.startsWith("👋")?"👋":"🗺"}</span>
                  <div style={{flex:1}}>
                    <p style={{color:t.text,fontFamily:"'DM Sans',sans-serif",fontSize:14,margin:"0 0 3px",lineHeight:1.4}}>{n.text}</p>
                    <p style={{color:t.text3,fontFamily:"'DM Mono',monospace",fontSize:10,margin:0}}>{n.time}</p>
                  </div>
                  {!n.read&&<div style={{width:8,height:8,borderRadius:"50%",background:t.accent,marginTop:6,flexShrink:0}}/>}
                </div>
              ))}
            </div>
          )}

          {/* MAP */}
          {page==="map"&&(
            <div style={{position:"absolute",inset:0,display:"flex",flexDirection:"column"}}>
              <MapPage activities={activities} currentUser={currentUser} userPos={userPos} onRequestLocation={requestLocation} viewRef={mapViewRef} onOpenActivity={(a)=>{ setSelected(a); setDetailBack("map"); setPage("detail"); }} t={t} />
            </div>
          )}

          {/* MESSAGES */}
          {page==="messages"&&(
            <div style={{paddingBottom:BOTTOM_NAV_H+16}}>
              <MessagesPage friends={allUsers.filter(u=>friendIds.includes(u.id))} last={lastDMs} myId={me0.id} onOpenDM={openDM} onGoFriends={()=>setPage("friends")} t={t} />
            </div>
          )}

          {/* FRIENDS */}
          {page==="friends"&&(
            <div style={{paddingBottom:BOTTOM_NAV_H+16}}>
              <FriendsPage currentUser={me} allUsers={allUsers} onOpenProfile={setProfileUser} onAcceptFriend={acceptFriendReq} onBack={()=>setPage("home")} onOpenDM={openDM} t={t} />
            </div>
          )}

          {/* MY PROFILE */}
          {page==="profile"&&(
            <div style={{paddingBottom:BOTTOM_NAV_H+16}}>
              <MyProfilePage currentUser={me} onUpdate={updateCurrentUser} onBack={()=>setPage("home")} onGoSettings={()=>setPage("settings")} t={t} />
            </div>
          )}

          {/* SETTINGS */}
          {page==="settings"&&(
            <div style={{paddingBottom:BOTTOM_NAV_H+16}}>
              <SettingsPage currentUser={me} darkMode={darkMode} onToggleDark={toggleDark} onLogout={handleLogout} onBack={()=>setPage("profile")} onChangePassword={()=>setShowPassword(true)} onOpenBlocked={()=>setShowBlocked(true)} onDeleteAccount={()=>setShowDelete(true)} blockedCount={blockedIds.length} t={t} />
            </div>
          )}
        </div>

        {/* DM — replaces everything */}
        {page==="dm"&&dmPartner&&(
          <div style={{position:"fixed",inset:0,background:t.bg,zIndex:80,display:"flex",flexDirection:"column"}}>
            <DMChat currentUser={currentUser} otherUser={dmPartner} messages={dmMessages} onSend={sendDM} onVoiceSend={sendVoiceDM} onSendMedia={sendMediaDM} onSendGif={sendGifDM} onStatus={sendStatus} partnerStatus={partnerStatus} onOpenProfile={()=>setProfileUser(dmPartner)} onBack={()=>setPage("messages")} t={t} />
          </div>
        )}

        {/* ── BOTTOM NAV BAR (Instagram style) ── */}
        {showNav&&(
          <div style={{height:`calc(${BOTTOM_NAV_H}px + env(safe-area-inset-bottom, 0px))`,borderTop:`1px solid ${t.border}`,background:t.navBg,display:"flex",alignItems:"center",justifyContent:"space-around",padding:"0 8px env(safe-area-inset-bottom, 0px)",flexShrink:0,zIndex:60,position:"relative"}}>
            {/* gradient top border */}
            <div style={{position:"absolute",top:0,left:0,right:0,height:2,background:t.gradient,opacity:0.6}}/>
            {NAV.map(({id,icon})=>{
              const active = page===id || (id==="notifs"&&page==="notifs");
              const isCreate = id==="create";
              return (
                <button
                  key={id}
                  onClick={()=>handleNavClick(id)}
                  style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",background:"none",border:"none",cursor:"pointer",color:active?"#E8008A":t.text3,padding:"6px 0",gap:3,transition:"color 0.15s",position:"relative"}}
                >
                  {icon(active)}
                  {!isCreate&&(
                    <span style={{fontSize:9,fontFamily:"'DM Mono',monospace",letterSpacing:"0.04em",color:active?"#E8008A":t.text3,fontWeight:active?700:400,marginTop:1}}>
                      {id==="home"?"Accueil":id==="messages"?"Messages":id==="map"?"Carte":id==="friends"?"Amis":"Profil"}
                    </span>
                  )}
                  {active&&!isCreate&&(
                    <div style={{position:"absolute",top:0,left:"50%",transform:"translateX(-50%)",width:20,height:2,borderRadius:1,background:t.gradient}}/>
                  )}
                </button>
              );
            })}
          </div>
        )}

        {/* ── NOTIF DROPDOWN (from top on notif icon click if on home) ── */}
        {showNotifs&&page!=="notifs"&&(
          <NotifPanel notifs={notifs} onMarkRead={markNotifsRead} onOpen={openNotif} onClose={()=>setShowNotifs(false)} t={t}/>
        )}

        {showGeoAsk && <GeoAskModal t={t}
          onAllow={()=>{ LS.set("grouz_geo_asked",true); setShowGeoAsk(false); requestLocation(); }}
          onLater={()=>{ LS.set("grouz_geo_asked",true); setShowGeoAsk(false); }} />}
        {showNearby && <NearbySheet t={t} users={nearby} loading={nearLoading} radius={nearbyRadius} onRadius={setNearbyRadius}
          geoStatus={geoStatus} hasPos={!!userPos} sharing={sharing} onToggleShare={toggleSharing} onAskLocation={requestLocation}
          onAdd={u=>sendFriendReq(u.id)} onOpenProfile={u=>setProfileUser(u)} onClose={()=>setShowNearby(false)} />}

        {/* ── PROFILE MODAL ── */}
        {profileUser&&(
          <ProfileModal
            user={profileUser}
            currentUser={currentUser}
            onClose={()=>setProfileUser(null)}
            onAddFriend={()=>{ sendFriendReq(profileUser.id); setProfileUser(null); }}
            onOpenDM={()=>{ setProfileUser(null); openDM(profileUser); }}
            onReport={()=>setReportTarget(profileUser)}
            onBlock={()=>blockUser(profileUser)}
            isFriend={isFriend(profileUser.id)}
            hasPendingReq={hasPendingReq(profileUser.id)}
            t={t}
          />
        )}

        {reportTarget && <ReportModal user={reportTarget} t={t} onClose={()=>setReportTarget(null)} onSend={sendReport} />}
        {showBlocked && <BlockedListModal users={allUsers.filter(u=>blockedIds.includes(u.id))} onUnblock={unblockUser} onClose={()=>setShowBlocked(false)} t={t} />}
        {showPassword && <PasswordForm t={t} onCancel={()=>setShowPassword(false)} onDone={()=>{ setShowPassword(false); alert("Mot de passe modifié ✅"); }} />}
        {showDelete && <DeleteAccountModal t={t} onClose={()=>setShowDelete(false)} onConfirm={deleteAccount} />}

        {/* CREATE MODAL */}
        {showCreate&&<CreateModal onClose={()=>setShowCreate(false)} onSave={handleCreate} currentUser={currentUser} t={t} />}
        </div>{/* end inner z-index wrapper */}
      </div>
    </>
  );
}
